import { clamp, dbToGain, midiToHz, seeded, TONIC_MIDI } from './harmony'
import { createScore, EVENTS, type Note, type Plan, type SoundContext, type SoundEvent } from './score'

/**
 * The instrument: plans from score.ts rendered with Web Audio, no audio files. Works on any
 * BaseAudioContext, so the same code plays in the app and renders offline for calibration and tests.
 */

/**
 * Bus level (dB) per event that meets its EVENTS loudness target. Generated by calibrate()
 * (measure.ts); re-run it after changing a voice, a chord, an event or a target.
 */
export const TRIM: Record<SoundEvent, number> = {
  select: -30.4,
  land: -30.7,
  merge: -30.1,
  wrong: -28.8,
  correct: -24.2,
  streak: -23.3,
  lessonEnd: -21.7,
  halfway: -20,
  milestone: -19.2,
  tap: -33.5,
  tab: -30.4,
  toggleOn: -34,
  toggleOff: -35.4,
  open: -35.7,
  close: -36.3,
  step: -34.9,
  lessonOpen: -28.9,
}

/** Boost ahead of the limiter: a phone speaker needs it, and overlaps are still caught. */
const MASTER_DB = 6
/** More overlapping events than this release the oldest. */
const MAX_LIVE = 6
/** A change of harmony fades older tails with this time constant, s. */
const PEDAL_TAU = 0.25
/**
 * Half-pedal: a new frequent or touch sound turns such sounds still ringing down by 9 dB just before its
 * contact, so a quick run of taps stays distinct while the chord keeps sounding underneath.
 */
const DUCK = dbToGain(-9)
const DUCK_TAU = 0.02
const DUCK_EARLY = 0.02

/** Sounds that come in quick runs: each new one ducks the others still ringing. */
const quick = (event: SoundEvent) => EVENTS[event].tier === 'frequent' || EVENTS[event].tier === 'touch'

/** Strike envelope: a short attack, a first decay to `hold` over `knee` s, then a straight dB line to −80 dB. */
function strike(
  param: AudioParam,
  at: number,
  peak: number,
  attack: number,
  ring: number,
  hold: number,
  knee: number,
) {
  param.setValueAtTime(0, at)
  param.linearRampToValueAtTime(peak, at + attack)
  const length = Math.max(0.06, ring - attack)
  const n = 128
  const curve = new Float32Array(n)
  const holdDb = 20 * Math.log10(hold)
  for (let i = 0; i < n; i++) {
    const x = (i / (n - 1)) * length
    const db =
      x < knee ? holdDb * (x / knee) : holdDb + (-80 - holdDb) * ((x - knee) / Math.max(1e-3, length - knee))
    curve[i] = peak * dbToGain(db)
  }
  curve[n - 1] = 0
  param.setValueCurveAtTime(curve, at + attack + 5e-4, length)
}

/** Swell envelope: an exponential approach over `rise` s, a long hold, then a fade to −80 dB. */
function swell(param: AudioParam, at: number, peak: number, rise: number, ring: number) {
  const n = 160
  const curve = new Float32Array(n)
  const tau = rise / 3
  for (let i = 0; i < n; i++) {
    const x = (i / (n - 1)) * ring
    const u = Math.max(0, (x - rise) / (ring - rise))
    curve[i] = peak * (1 - Math.exp(-x / tau)) * dbToGain(-80 * u ** 1.6)
  }
  curve[0] = 0
  curve[n - 1] = 0
  param.setValueCurveAtTime(curve, at, ring)
}

/** Generated once per context: contact noise and a room impulse response. */
const rooms = new WeakMap<BaseAudioContext, { noise: AudioBuffer; room: AudioBuffer }>()
function roomOf(ctx: BaseAudioContext) {
  const cached = rooms.get(ctx)
  if (cached) return cached
  const rate = ctx.sampleRate
  const random = seeded(12345)
  const noise = ctx.createBuffer(1, Math.floor(rate * 0.05), rate)
  const samples = noise.getChannelData(0)
  for (let i = 0; i < samples.length; i++) samples[i] = random() * 2 - 1
  // A small warm room: 20 ms pre-delay, five early reflections, then decorrelated noise per channel
  // decaying with RT60 2.3 s and darkening as it ages.
  const length = Math.floor(rate * 3.2)
  const preDelay = Math.floor(rate * 0.02)
  const room = ctx.createBuffer(2, length, rate)
  const reflections = [
    [0.009, 0.5],
    [0.017, -0.35],
    [0.026, 0.3],
    [0.037, -0.22],
    [0.051, 0.18],
  ] as const
  const fadeFrom = length - Math.floor(rate * 0.1)
  for (let channel = 0; channel < 2; channel++) {
    const data = room.getChannelData(channel)
    const r = seeded(987 + channel * 7919)
    let lowPassed = 0
    for (let i = preDelay; i < length; i++) {
      const t = (i - preDelay) / rate
      const darkening = 0.3 + 0.62 * Math.min(1, t / 1.6)
      lowPassed += (1 - darkening) * (r() * 2 - 1 - lowPassed)
      let value = lowPassed * Math.exp((-6.91 * t) / 2.3)
      if (i > fadeFrom) value *= (length - i) / (length - fadeFrom)
      data[i] = value
    }
    for (const [seconds, gain] of reflections) {
      const i = preDelay + Math.floor(seconds * rate * (channel ? 1.07 : 1))
      if (i < length) data[i] = (data[i] as number) + gain * (channel ? -1 : 1) * 0.6
    }
  }
  const made = { noise, room }
  rooms.set(ctx, made)
  return made
}

type Bus = {
  event: SoundEvent
  harmony: string
  fade: GainNode
  nodes: AudioNode[]
  sources: [AudioScheduledSourceNode, number][]
  released: boolean
  duck: number
}

export type SynthOptions = {
  random?: () => number
  /** Override the calibrated bus level (calibration renders with this). */
  levelDb?: number
  masterDb?: number
  /** false: the caller connects `output` itself. */
  connect?: boolean
}

export function createSynth(ctx: BaseAudioContext, options: SynthOptions = {}) {
  const random = options.random ?? Math.random
  const score = createScore(random)
  const { noise, room } = roomOf(ctx)

  const dry = ctx.createGain()
  const sendIn = ctx.createBiquadFilter()
  const reverb = ctx.createConvolver()
  const sum = ctx.createGain()
  sendIn.type = 'highpass'
  sendIn.frequency.value = 250
  reverb.normalize = true
  reverb.buffer = room
  // Limiter: a fast ratio-20 compressor that only acts on overlaps. Web Audio adds makeup gain of
  // (1 / gain at 0 dBFS)^0.6; the next gain cancels it, so the limiter never makes anything louder.
  const limiter = ctx.createDynamicsCompressor()
  const threshold = -6
  const ratio = 20
  limiter.threshold.value = threshold
  limiter.knee.value = 0
  limiter.ratio.value = ratio
  limiter.attack.value = 0.002
  limiter.release.value = 0.2
  const unMakeup = ctx.createGain()
  unMakeup.gain.value = dbToGain((threshold - threshold / ratio) * 0.6)
  const master = ctx.createGain()
  master.gain.value = dbToGain(options.masterDb ?? MASTER_DB)
  const output = ctx.createGain()
  dry.connect(sum)
  sendIn.connect(reverb).connect(sum)
  sum.connect(master).connect(limiter).connect(unMakeup).connect(output)
  if (options.connect !== false) output.connect(ctx.destination)

  const live: Bus[] = []

  function cleanup(bus: Bus) {
    for (const node of bus.nodes) node.disconnect()
    bus.nodes.length = 0
    bus.sources.length = 0
    const i = live.indexOf(bus)
    if (i >= 0) live.splice(i, 1)
  }

  function release(bus: Bus, at: number, tau: number) {
    if (bus.released) return
    bus.released = true
    bus.fade.gain.cancelScheduledValues(at)
    bus.fade.gain.setTargetAtTime(0, at, tau)
    for (const [source, stopAt] of bus.sources) {
      try {
        source.stop(Math.min(stopAt, at + tau * 8))
      } catch {
        // Already stopped.
      }
    }
  }

  function render(plan: Plan, levelDb: number) {
    const spec = EVENTS[plan.event]
    const nodes: AudioNode[] = []
    const sources: [AudioScheduledSourceNode, number][] = []
    const add = <T extends AudioNode>(node: T) => {
      nodes.push(node)
      return node
    }
    const fade = add(ctx.createGain())
    const lowPass = add(ctx.createBiquadFilter())
    const level = add(ctx.createGain())
    const send = add(ctx.createGain())
    lowPass.type = 'lowpass'
    lowPass.frequency.value = spec.cutoff
    lowPass.Q.value = 0.5
    level.gain.value = dbToGain(levelDb)
    send.gain.value = 0.3 * spec.wet
    fade.connect(lowPass).connect(level).connect(dry)
    level.connect(send).connect(sendIn)

    let last: AudioScheduledSourceNode | null = null
    let lastStop = -1
    const start = (source: AudioScheduledSourceNode, at: number, stopAt: number) => {
      source.start(at)
      source.stop(stopAt)
      sources.push([source, stopAt])
      if (stopAt > lastStop) {
        lastStop = stopAt
        last = source
      }
    }
    const osc = (type: OscillatorType, hz: number, at: number, stopAt: number, detune: number) => {
      const o = add(ctx.createOscillator())
      o.type = type
      o.frequency.value = hz
      o.detune.value = detune
      start(o, at, stopAt)
      return o
    }
    const gain = () => add(ctx.createGain())
    const amp = (pan: number) => {
      const g = gain()
      const panner = add(ctx.createStereoPanner())
      panner.pan.value = pan
      g.connect(panner).connect(fade)
      return g
    }

    for (const note of plan.notes) {
      if (note.kind === 'thump') {
        // A value landing: 30 ms of band-passed noise with a 1.5 ms attack.
        const source = add(ctx.createBufferSource())
        const band = add(ctx.createBiquadFilter())
        const g = gain()
        source.buffer = noise
        band.type = 'bandpass'
        band.frequency.value = 900
        band.Q.value = 0.9
        g.gain.setValueAtTime(0, note.at)
        g.gain.linearRampToValueAtTime(note.velocity, note.at + 0.0015)
        g.gain.exponentialRampToValueAtTime(note.velocity * 1e-4, note.at + 0.03)
        g.gain.setValueAtTime(0, note.at + 0.031)
        source.connect(band).connect(g).connect(fade)
        start(source, note.at, note.at + 0.045)
        continue
      }
      // A player is never exact: a few cents of detune, ±6 % velocity, up to 4 ms late.
      const detune = (random() * 2 - 1) * 4
      const velocity = note.velocity * (1 + (random() * 2 - 1) * 0.06)
      const at = note.at + (note.kind === 'main' && note.bright > 0.05 ? random() * 0.004 : 0)
      const hz = midiToHz(TONIC_MIDI + note.pitch)
      const pan = clamp((TONIC_MIDI + note.pitch - 66) / 34, -0.3, 0.3)
      const stopAt = at + note.ring + 0.05
      const played: Note = { ...note, at, velocity }

      if (note.kind === 'pad' || note.kind === 'halo') {
        // Two detuned triangles (pad) or sines (halo) swelling in.
        const a = amp(pan)
        swell(a.gain, at, played.velocity * 0.3, note.rise ?? 0.6, note.ring)
        for (const cents of [-7, 7])
          osc(note.kind === 'pad' ? 'triangle' : 'sine', hz, at, stopAt, detune + cents).connect(a)
      } else if (note.kind === 'shine') {
        // Glass: a sine with a 5-cent twin and soft 2nd and 4th partials.
        const a = amp(pan)
        const partials = [
          [1, 0.7, 1, 0],
          [1, 0.3, 1, 5],
          [2, 0.06, 0.5, 0],
          [4, 0.05 + 0.06 * note.bright, 0.2, 0],
        ] as const
        for (const [ratioOf, level, ringOf, cents] of partials) {
          if (hz * ratioOf > 12000) continue
          const g = gain()
          strike(g.gain, at, velocity * level, 0.006, Math.max(0.15, note.ring * ringOf), 0.55, 0.25)
          osc('sine', hz * ratioOf, at, stopAt, detune + cents)
            .connect(g)
            .connect(a)
        }
      } else {
        // Electric piano: FM with a 1:1 modulator for the warm body (its index falls) and a short 14:1 tine.
        const a = amp(pan)
        strike(a.gain, at, velocity, 0.008, note.ring, 0.5, 0.3)
        const carrier = osc('sine', hz, at, stopAt, detune)
        const modulator = osc('sine', hz, at, stopAt, detune)
        const depth = gain()
        const index = hz * (0.3 + 1.1 * note.bright)
        depth.gain.setValueAtTime(index, at)
        depth.gain.exponentialRampToValueAtTime(index * 0.08, at + Math.min(note.ring, 0.9))
        modulator.connect(depth).connect(carrier.frequency)
        if (TONIC_MIDI + note.pitch < 84 && note.bright > 0.1) {
          const tine = osc('sine', hz * 14, at, at + 0.1, detune)
          const tineDepth = gain()
          tineDepth.gain.setValueAtTime(hz * 0.2 * note.bright, at)
          tineDepth.gain.exponentialRampToValueAtTime(hz * 0.002, at + 0.07)
          tine.connect(tineDepth).connect(carrier.frequency)
        }
        carrier.connect(a)
      }
    }

    const bus: Bus = {
      event: plan.event,
      harmony: plan.harmony,
      fade,
      nodes,
      sources,
      released: false,
      duck: 1,
    }
    if (last) (last as AudioScheduledSourceNode).onended = () => cleanup(bus)
    return bus
  }

  /** Plays `event` at context time `when` (default: now). Returns the plan, in context time. */
  function play(event: SoundEvent, context: SoundContext = {}, when?: number): Plan {
    const now = ctx.currentTime
    const start = Math.max(when ?? now + 0.01, now + 0.005)
    const plan = score.plan(event, context, start)
    // Pedal: a different harmony, or any multi-chord event, fades the tails still ringing.
    if (EVENTS[event].pedal !== false)
      for (const bus of live)
        if (plan.harmony === '*' || bus.harmony !== plan.harmony) release(bus, start, PEDAL_TAU)
    if (quick(event)) {
      const duckAt = Math.max(now, start - DUCK_EARLY)
      for (const bus of live) {
        if (bus.released || !quick(bus.event)) continue
        bus.duck *= DUCK
        bus.fade.gain.cancelScheduledValues(duckAt)
        bus.fade.gain.setTargetAtTime(bus.duck, duckAt, DUCK_TAU)
      }
    }
    const ringing = live.filter((bus) => !bus.released)
    for (let i = 0; i <= ringing.length - MAX_LIVE; i++) release(ringing[i] as Bus, start, 0.15)
    live.push(render(plan, options.levelDb ?? TRIM[event]))
    return plan
  }

  function stopAll() {
    const now = ctx.currentTime
    for (const bus of [...live]) release(bus, now, 0.03)
  }

  return {
    output,
    play,
    stopAll,
    get ringing() {
      return live.length
    },
  }
}

export type Synth = ReturnType<typeof createSynth>
